// Hold src/services/spPayjoin.ts to the Python reference.
//
//   node scripts/check-payjoin-signing.mjs [path/to/payjoin-sp.json]
//
// Vectors come from siLNt helpers/_payjoin_sp_fixtures.py, generated by calling
// the same functions helpers/payjoin_sp.py gives the endpoints. Regenerate them
// after any change to the derivation, the fee formula, the input ordering or
// the output ordering — on either side.
//
// WHY THIS RUNNER MATTERS MORE THAN THE OTHER TWO. In an ordinary send, a
// derivation mistake makes an output the recipient's scanner cannot find: bad,
// and one party's bug. In a PayJoin the two parties derive different outputs of
// the SAME transaction from the SAME frozen input set, and each signs over
// both. If the client's A_sum or input_hash differs from the server's by one
// byte, both parties derive outputs that belong to nobody, both signatures
// still verify, and the network accepts it. Detected-and-unspendable, for two
// people at once, with no error raised anywhere.
//
// So A_sum is compared in its COMPRESSED form, parity byte included. The parity
// is the half that produces unspendable outputs silently, and an x-only
// comparison would not see it.
//
// Signatures are not compared byte for byte — BIP-340 uses random aux data, so
// they differ every time. They are verified against the sighash instead, which
// is what the network does.

import { readFileSync } from 'node:fs';
import { register } from 'node:module';
import { pathToFileURL } from 'node:url';

register('./ts-resolve.mjs', import.meta.url);

const FIXTURES = process.argv[2] || '../../siLNt/fixtures/payjoin-sp.json';

let failed = 0;
function ok(name, cond, detail = '') {
  console.log((cond ? '  ok   ' : '  FAIL ') + name);
  if (!cond) {
    if (detail) console.log('         ' + detail);
    failed++;
  }
}

const pj = await import(
  pathToFileURL(new URL('../src/services/spPayjoin.ts', import.meta.url).pathname).href
);
const sp = await import(
  pathToFileURL(new URL('../src/services/spSign.ts', import.meta.url).pathname).href
);
const { schnorr } = await import('@noble/curves/secp256k1');

const { toHex, fromHex } = sp;

const data = JSON.parse(
  readFileSync(new URL(FIXTURES, import.meta.url), 'utf8'),
);

for (const c of data.cases) {
  console.log('\n' + c.name);
  const e = c.expected;
  const payerIn = c.payer.inputs;
  const payeeIn = c.payee.inputs;
  const all = [...payerIn, ...payeeIn];

  // ── the shared digest both parties must agree on ──
  const { aSum, inputHash } = pj.inputDigest(all);
  ok('A_sum matches, parity byte included',
    toHex(aSum) === e.a_sum,
    `js ${toHex(aSum)} py ${e.a_sum}`);
  ok('input_hash matches',
    inputHash.toString(16).padStart(64, '0') === e.input_hash,
    `js ${inputHash.toString(16).padStart(64, '0')} py ${e.input_hash}`);

  // ── each party's own output, derived from its own scan key ──
  const paymentSpk = pj.paymentScript(
    c.payee.scan_secret, fromHex(c.payee.spend_pub), all,
  );
  ok('the payee derives the payment script the server expects',
    toHex(paymentSpk) === e.payment_spk,
    `js ${toHex(paymentSpk)} py ${e.payment_spk}`);

  let changeSpk = null;
  if (e.change_spk) {
    changeSpk = pj.changeScript(
      c.payer.scan_secret, fromHex(c.payer.spend_pub), all,
    );
    ok('the payer derives its m=0 labelled change script',
      toHex(changeSpk) === e.change_spk,
      `js ${toHex(changeSpk)} py ${e.change_spk}`);
  } else {
    ok('no change script where the change was absorbed', e.change === 0);
  }

  // ── amounts ──
  let amounts;
  try {
    amounts = pj.plan(payerIn, payeeIn, c.amount, c.fee_rate);
  } catch (err) {
    ok('amounts', false, String(err));
    continue;
  }
  for (const [field, want] of [
    ['payer_in', e.payer_in], ['payee_in', e.payee_in],
    ['payment', e.payment], ['change', e.change],
    ['fee', e.fee], ['vsize', e.vsize],
  ]) {
    ok(field, amounts[field] === want, `js ${amounts[field]} py ${want}`);
  }

  // ── the transaction ──
  const assembled = pj.assemble(all, amounts, paymentSpk, changeSpk);
  ok('input order is canonical, not submission order',
    JSON.stringify(assembled.vin.map((i) => `${i.txid}:${i.vout}`)) ===
      JSON.stringify(e.input_order),
    `js ${assembled.vin.map((i) => `${i.txid}:${i.vout}`).join(',')}`);
  ok('output values are BIP-69 ordered and match',
    JSON.stringify(assembled.vout.map((o) => o.value)) ===
      JSON.stringify(e.output_values));
  ok('output scripts match',
    JSON.stringify(assembled.vout.map((o) => toHex(o.script))) ===
      JSON.stringify(e.output_scripts));
  ok('the unsigned transaction is identical',
    assembled.unsignedHex === e.unsigned_tx,
    `js ${assembled.unsignedHex}\n         py ${e.unsigned_tx}`);

  // ── who signs what ──
  ok('the payer signs its own input positions',
    JSON.stringify(pj.ownIndices(all, payerIn)) === JSON.stringify(e.payer_indices),
    `js ${pj.ownIndices(all, payerIn)} py ${e.payer_indices}`);
  ok('the payee signs its own input positions',
    JSON.stringify(pj.ownIndices(all, payeeIn)) === JSON.stringify(e.payee_indices),
    `js ${pj.ownIndices(all, payeeIn)} py ${e.payee_indices}`);

  // ── sighashes, and signatures that verify against them ──
  const ordered = pj.canonical(all);
  const digests = ordered.map((_i, n) =>
    sp.taprootSighash(assembled.vin, assembled.vout, n, assembled.amounts, assembled.scripts),
  );
  ok('every sighash matches',
    JSON.stringify(digests.map(toHex)) === JSON.stringify(e.sighashes),
    `js ${digests.map(toHex).join(',')}\n         py ${e.sighashes.join(',')}`);

  for (const [who, party, mine, indices] of [
    ['payer', c.payer, payerIn, e.payer_indices],
    ['payee', c.payee, payeeIn, e.payee_indices],
  ]) {
    const sigs = pj.signOwnInputs(assembled, all, mine, party.spend_secret);
    ok(`the ${who} signs exactly its own inputs`,
      JSON.stringify(Object.keys(sigs).map(Number).sort((a, b) => a - b)) ===
        JSON.stringify(indices));
    let allVerify = true;
    for (const [n, hex] of Object.entries(sigs)) {
      if (!schnorr.verify(fromHex(hex), digests[Number(n)], fromHex(ordered[Number(n)].pub_key))) {
        allVerify = false;
      }
    }
    ok(`every ${who} signature verifies against the input's on-chain key`, allVerify);
  }
}

// ── the guards: what each side refuses to sign ───────────────────────────────
//
// The asymmetry is the whole security model. The payee checks the payment
// output by script because it derived it; the payer cannot, so it checks that
// output by value and its own change by script. These cases are the ways a
// coordinator could try to profit from the difference.

console.log('\nguards');
{
  const c = data.cases[0];
  const payerIn = c.payer.inputs;
  const payeeIn = c.payee.inputs;
  const all = [...payerIn, ...payeeIn];
  const amounts = pj.plan(payerIn, payeeIn, c.amount, c.fee_rate);
  const paymentSpk = pj.paymentScript(c.payee.scan_secret, fromHex(c.payee.spend_pub), all);
  const changeSpk = pj.changeScript(c.payer.scan_secret, fromHex(c.payer.spend_pub), all);

  // paymentSpk/changeSpk are what the SERVER holds; expect* are what this
  // device derived. Keeping them apart is what makes these checks real — the
  // substitutions below change the server's copy and leave expect* alone.
  const base = {
    role: 'payer', inputs: all, mine: payerIn, amounts,
    paymentSpk, changeSpk, expectChangeSpk: changeSpk, committed: payerIn,
    amount: c.amount, feeRate: c.fee_rate,
  };

  let threw = null;
  try { pj.checkBeforeSigning(base); } catch (err) { threw = err; }
  ok('an honest PayJoin passes the payer\'s checks', threw === null, String(threw));

  threw = null;
  try {
    pj.checkBeforeSigning({
      ...base, role: 'payee', mine: payeeIn, committed: payeeIn,
      expectChangeSpk: null, expectPaymentSpk: paymentSpk,
    });
  } catch (err) { threw = err; }
  ok('an honest PayJoin passes the payee\'s checks', threw === null, String(threw));

  const refuses = (name, opts, match) => {
    let err = null;
    try { pj.checkBeforeSigning(opts); } catch (e2) { err = e2; }
    ok(name, err !== null && new RegExp(match).test(err.message),
      err ? err.message : 'it was accepted');
  };

  refuses('the payer refuses a fee it did not compute',
    { ...base, amounts: { ...amounts, fee: amounts.fee + 5000 } },
    'this device computes');

  refuses('the payer refuses change sent to a script it did not derive',
    { ...base, changeSpk: fromHex('5120' + 'ff'.repeat(32)) },
    'change is not going where');

  refuses('the payer refuses a payment output bigger than agreed',
    { ...base, amounts: { ...amounts, payment: amounts.payment + 10_000 } },
    'this device computes|not for the agreed amount');

  refuses('the payer refuses an input set that is not what it chose',
    { ...base, committed: [{ ...payerIn[0], vout: payerIn[0].vout + 7 }] },
    'not the ones you chose');

  refuses('the payer refuses its own coin listed at the wrong amount',
    { ...base, committed: [{ ...payerIn[0], amount: payerIn[0].amount + 1 }] },
    'wrong amount');

  refuses('the payee refuses a payment to a script it did not derive',
    {
      ...base, role: 'payee', mine: payeeIn, committed: payeeIn,
      expectChangeSpk: null, expectPaymentSpk: paymentSpk,
      paymentSpk: fromHex('5120' + 'ee'.repeat(32)),
    },
    'not to the address this device derived');

  // Signing without the tweak is signing for someone else's coin.
  let err = null;
  try {
    pj.signOwnInputs(
      pj.assemble(all, amounts, paymentSpk, changeSpk), all,
      payeeIn.map(({ priv_key_tweak, ...rest }) => rest),
      c.payee.spend_secret,
    );
  } catch (e2) { err = e2; }
  ok('an input with no tweak cannot be signed',
    err !== null && /no tweak for it/.test(err.message),
    err ? err.message : 'it was signed');

  err = null;
  try {
    pj.signOwnInputs(
      pj.assemble(all, amounts, paymentSpk, changeSpk), all, payeeIn,
      c.payer.spend_secret,
    );
  } catch (e2) { err = e2; }
  ok('the wrong spend key cannot sign a coin',
    err !== null && /does not match this coin/.test(err.message),
    err ? err.message : 'it was signed');
}

console.log(
  failed
    ? `\n${failed} check(s) failed`
    : '\nall checks passed — both parties derive what the server derives',
);
process.exit(failed ? 1 : 0);
